diff --git a/.claude/scripts/loa-status.sh b/.claude/scripts/loa-status.sh
index c93b43df..8ee6cc50 100755
--- a/.claude/scripts/loa-status.sh
+++ b/.claude/scripts/loa-status.sh
@@ -788,9 +788,27 @@ _provider_key_present() {  # $1 provider → "present (env)" | "present (.env.lo
   done
   echo absent
 }
-_provider_hop() {  # $1 provider → hop binary name or ""
+_providers_config_file() {  # the Loa config the Providers block reads (bats-gated seam: LOA_STATUS_CONFIG_FILE)
+  if [[ -n "${BATS_TEST_FILENAME:-}${BATS_VERSION:-}" && -n "${LOA_STATUS_CONFIG_FILE:-}" ]]; then
+    echo "$LOA_STATUS_CONFIG_FILE"
+  else
+    echo "$CONFIG_FILE"
+  fi
+}
+_agy_opted_in() {  # cycle-127 FR-1: true only for a YAML boolean true at hounfour.headless.agy_opt_in (no env override)
+  local cfg v=""; cfg=$(_providers_config_file)
+  [[ -f "$cfg" ]] && command -v yq >/dev/null 2>&1 || return 1
+  v=$(yq eval '.hounfour.headless.agy_opt_in | (tag == "!!bool" and . == true)' "$cfg" 2>/dev/null) || v=""
+  [[ "$v" == "true" ]]
+}
+_AGY_OPT_IN_NOTE="agy: opt-in (disabled; hounfour.headless.agy_opt_in)"
+_provider_hop_note() {  # $1 provider → the hop note when its CLI route is gated off, else ""
+  [[ "$1" == "google" ]] && ! _agy_opted_in && echo "$_AGY_OPT_IN_NOTE" || echo ""
+}
+_provider_hop() {  # $1 provider → hop binary name or "" (the agy hop is "" while its opt-in is off — cycle-127 FR-1)
   local bin=""
   case "$1" in anthropic) bin=claude ;; openai) bin=codex ;; google) bin=agy ;; esac
+  [[ "$bin" == agy ]] && ! _agy_opted_in && { echo ""; return 0; }
   [[ -n "$bin" ]] && command -v "$bin" >/dev/null 2>&1 && echo "$bin" || echo ""
 }
 _fmt_age_s() { local s="$1"; if [[ ! "$s" =~ ^[0-9]+$ ]]; then echo "-"; elif (( s >= 86400 )); then echo "$(( s / 86400 ))d"; elif (( s >= 3600 )); then echo "$(( s / 3600 ))h"; else echo "$(( s / 60 ))m"; fi; }
@@ -830,8 +848,10 @@ get_providers_json() {
   local out='{}'
   for p in $(printf '%s\n' $provs | sort -u); do
     out=$(printf '%s' "$out" | jq -c --arg p "$p" --arg key "$(_provider_key_present "$p")" --arg hop "$(_provider_hop "$p")" \
+      --arg note "$(_provider_hop_note "$p")" \
       --argjson buckets "$(printf '%s' "$snap" | jq -c --arg p "$p" '.buckets[$p] // {}')" \
-      '.[$p] = {credential:$key, cli_hop:(if $hop == "" then null else $hop end), breakers:$buckets}')
+      '.[$p] = ({credential:$key, cli_hop:(if $hop == "" then null else $hop end), breakers:$buckets}
+                + (if $note == "" then {} else {cli_hop_note:$note} end))')
   done
   out=$(printf '%s' "$out" | jq -c --argjson c "$(_anthropic_ceiling_json)" 'if has("anthropic") then .anthropic.ceiling = $c else . end')
   printf '%s' "$out" | jq -c --argjson rt "$(printf '%s' "$snap" | jq '.reset_timeout_seconds // 60')" '{reset_timeout_seconds:$rt, providers:.}'
@@ -842,7 +862,7 @@ display_providers_section() {
   echo -e "${BOLD}Providers${NC}"
   while IFS= read -r p; do
     [[ -n "$p" ]] || continue
-    key=$(printf '%s' "$pj" | jq -r --arg p "$p" '.providers[$p].credential'); hop=$(printf '%s' "$pj" | jq -r --arg p "$p" '.providers[$p].cli_hop // "-"')
+    key=$(printf '%s' "$pj" | jq -r --arg p "$p" '.providers[$p].credential'); hop=$(printf '%s' "$pj" | jq -r --arg p "$p" '.providers[$p].cli_hop_note // .providers[$p].cli_hop // "-"')
     line=$(printf '  %-10s key %-20s hop %-7s' "$p" "$key" "$hop")
     local buckets; buckets=$(printf '%s' "$pj" | jq -r --arg p "$p" '.providers[$p].breakers | to_entries[] | "\(.key) \(.value.state) \(.value.age_s // "-") \(.value.probe_due_in_s // "-")"')
     if [[ -z "$buckets" ]]; then line+=" no breaker state"; else
diff --git a/.claude/scripts/run-preflight.sh b/.claude/scripts/run-preflight.sh
index cf16a046..9341da3f 100755
--- a/.claude/scripts/run-preflight.sh
+++ b/.claude/scripts/run-preflight.sh
@@ -151,6 +151,13 @@ cred_present() {  # $1 = provider → 0 if a credential is present (env / .env.l
   return 1
 }
 cli_for() { case "$1" in claude-headless) echo claude ;; codex-headless) echo codex ;; gemini-headless) echo agy ;; *) echo "" ;; esac; }
+agy_opted_in() {  # cycle-127 FR-1: true only for a YAML boolean true at hounfour.headless.agy_opt_in (no env override)
+  local v=""
+  have_yq && [[ -f "$ROOT/.loa.config.yaml" ]] || return 1
+  if [[ "$YQ_FLAVOUR" == "go" ]]; then v=$(yq eval '.hounfour.headless.agy_opt_in | (tag == "!!bool" and . == true)' "$ROOT/.loa.config.yaml" 2>/dev/null) || v=""
+  else v=$(yq '.hounfour.headless.agy_opt_in == true' "$ROOT/.loa.config.yaml" 2>/dev/null) || v=""; fi
+  [[ "$v" == "true" ]]
+}
 provider_of() {  # $1 = model id → openai|anthropic|google|""
   local id="$1" alias="" cat=""
   # Only catalog-shaped ids reach the yq expression (config text is operator-owned but is still input).
@@ -169,7 +176,7 @@ provider_of() {  # $1 = model id → openai|anthropic|google|""
 }
 declare -A USABLE_PROVIDERS=()   # providers that have a usable voice in any stage
 declare -A STAGE_ONLY=()         # stage → the single usable provider (for P4)
-p3_status="PASS"; p3_detail=""; p3_fail_stages=""; p3_warn=""; p3_usable=""
+p3_status="PASS"; p3_detail=""; p3_fail_stages=""; p3_warn=""; p3_usable=""; p3_optin=""
 if ! have_yq || [[ ! -f "$ROOT/.loa.config.yaml" ]]; then
   p3_status="WARN"; p3_detail="yq or .loa.config.yaml missing: voices unchecked"
 else
@@ -179,6 +186,8 @@ else
     usable=0; missing=""; provs=""; usable_names=""
     for m in $models $chain; do
       prov=$(provider_of "$m"); cli=$(cli_for "$m"); ok=0
+      # (an agy hop whose opt-in is off is not a voice on any host — never usable, never "missing a CLI")
+      if [[ "$cli" == agy ]] && ! agy_opted_in; then [[ " $p3_optin " == *" $m(agy: opt-in (disabled; hounfour.headless.agy_opt_in)) "* ]] || p3_optin+="$m(agy: opt-in (disabled; hounfour.headless.agy_opt_in)) "; continue; fi
       if [[ -n "$cli" ]] && command -v "$cli" >/dev/null 2>&1; then ok=1
       elif [[ -z "$cli" && -n "$prov" ]] && cred_present "$prov"; then ok=1; fi
       if (( ok )); then usable=$((usable + 1)); USABLE_PROVIDERS["${prov:-$m}"]=1; provs+="${prov:-$m} "; usable_names+="$m${cli:+(cli $cli)} "
@@ -195,6 +204,8 @@ else
   if [[ -n "$p3_fail_stages" ]]; then p3_status="FAIL"; p3_detail="no usable voice for ${p3_fail_stages% }: no credential present and no CLI hop on PATH"
   elif [[ -n "$p3_warn" ]]; then p3_status="WARN"; p3_detail="${p3_usable}${p3_warn%; }"
   else p3_detail="every configured voice has a credential or CLI hop (${p3_usable%; })"; fi
+  # (cycle-127 FR-1: a hop not planned by its opt-in is said, never counted as a missing voice)
+  [[ -z "$p3_optin" ]] || p3_detail+="; not planned: ${p3_optin% }"
 fi
 record P3 voices "$p3_status" "$p3_detail" "export OPENAI_API_KEY / ANTHROPIC_API_KEY / GOOGLE_API_KEY (or put them in .env.local), or install a CLI hop (claude, codex, agy) named in the stage's fallback_chain"

